// ─── File: ContractEvolutionDemo.java ───
// Runnable demo: publish a v2 (additive) event; an OLD v1 consumer still reads it.
package com.bank.contract;

import java.math.BigDecimal;
import java.util.logging.*;

public class ContractEvolutionDemo {

    private static final Logger log = Logger.getLogger("Contract");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Internal entity — represents the DB row. NEVER published directly.
        AccountEntity rajesh = new AccountEntity("SAV2001", "Rajesh Kumar",
                new BigDecimal("1000000.00"), "NBIN-MUM-001");

        EventPublisher publisher = new EventPublisher();
        // Publisher maps entity → explicit event (v2 adds optional 'channel').
        AccountCreditedEvent event =
                publisher.buildCreditedEvent(rajesh, new BigDecimal("50000.00"), "UPI");
        log.info(() -> "PUBLISHED v" + event.schemaVersion + ": " + event);

        // Old v1 consumer ignores the new 'channel' field → still works (additive).
        StatementConsumerV1 oldConsumer = new StatementConsumerV1();
        oldConsumer.onEvent(event);
    }
}

// ─── entity/AccountEntity.java (INTERNAL — @Entity in real code; never on the wire) ───
class AccountEntity {
    final String accountId, holderName, branchCode;
    final BigDecimal balance;
    AccountEntity(String id, String name, BigDecimal bal, String branch) {
        this.accountId = id; this.holderName = name; this.balance = bal; this.branchCode = branch;
    }
}

// ─── event/AccountCreditedEvent.java (PUBLISHED contract — governed like an API) ───
class AccountCreditedEvent {
    int schemaVersion = 2;          // explicit contract version
    String accountId;
    MoneyAmount amount;             // explicit money: value + currency + scale (no semantic ambiguity)
    String channel;                 // v2 ADDED — optional, default null → backward compatible
    long occurredAtEpochMs;
    @Override public String toString() {
        return "AccountCreditedEvent{acc=" + accountId + ", amount=" + amount
                + ", channel=" + channel + ", at=" + occurredAtEpochMs + "}";
    }
}

// Explicit money type so units/semantics are NEVER ambiguous (avoids semantic breaks).
class MoneyAmount {
    BigDecimal value; String currency;
    MoneyAmount(BigDecimal value, String currency) { this.value = value; this.currency = currency; }
    @Override public String toString() { return value + " " + currency; }
}

// ─── publisher/EventPublisher.java (deliberate mapping entity → event) ───
class EventPublisher {
    private static final Logger log = Logger.getLogger("Contract");
    AccountCreditedEvent buildCreditedEvent(AccountEntity acc, BigDecimal credit, String channel) {
        AccountCreditedEvent e = new AccountCreditedEvent();
        e.accountId = acc.accountId;
        e.amount = new MoneyAmount(credit, "INR");   // explicit currency — no ambiguity
        e.channel = channel;                          // new optional field
        e.occurredAtEpochMs = System.currentTimeMillis();
        log.fine(() -> "Mapped AccountEntity → AccountCreditedEvent (not entity-on-wire)");
        return e;
    }
}

// ─── consumer/StatementConsumerV1.java (written against v1; knows nothing of 'channel') ───
class StatementConsumerV1 {
    private static final Logger log = Logger.getLogger("Contract");
    void onEvent(AccountCreditedEvent e) {
        // v1 consumer reads only fields it knows; ignores 'channel' → safe, additive.
        log.info(() -> "V1 consumer posted statement line: credited "
                + e.amount + " to " + e.accountId + " (channel ignored by v1)");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
